<script setup lang="ts">
/**
 * Markdown.Inlines: a block’s inline nodes, each as the member or element that draws its kind.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/markdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { inlineText, type MarkdownInline } from '@polymorph/vue'
import styles from '@polymorph/recipes/ai/markdown.module.css'
import Citation from './Citation.vue'
import Code from '../structure/Code.vue'
import Link from '../controls/Link.vue'
import type { CitationSource } from './SourceList.vue'

export interface MarkdownInlinesProps {
  nodes: MarkdownInline[]
  sources: CitationSource[]
}

defineOptions({ name: 'MarkdownInlines', inheritAttrs: false })

defineProps<MarkdownInlinesProps>()
</script>

<template>
  <template v-for="(node, index) in nodes" :key="index">
    <template v-if="node.kind === 'text'">{{ node.text }}</template>
    <Code v-else-if="node.kind === 'code'">
      {{ node.text }}
    </Code>
    <strong v-else-if="node.kind === 'strong'">
      <MarkdownInlines :nodes="node.children" :sources="sources" />
    </strong>
    <em v-else-if="node.kind === 'em'">
      <MarkdownInlines :nodes="node.children" :sources="sources" />
    </em>
    <s v-else-if="node.kind === 'strike'">
      <MarkdownInlines :nodes="node.children" :sources="sources" />
    </s>
    <br v-else-if="node.kind === 'break'" />
    <Link
      v-else-if="node.kind === 'link'"
      :href="node.href"
      :external="/^(https?:|mailto:|\/\/)/i.test(node.href)"
    >
      {{ inlineText(node.children) }}
    </Link>
    <!-- image -->
    <img
      v-else-if="node.kind === 'image'"
      :class="styles.image"
      :src="node.src"
      :alt="node.alt"
      loading="lazy"
      draggable="false"
    />
    <Citation
      v-else-if="node.kind === 'citation' && sources[node.index - 1] !== undefined"
      :index="node.index"
      :source="sources[node.index - 1]!"
    />
    <template v-else-if="node.kind === 'citation'">{{ `[${node.index}]` }}</template>
  </template>
</template>
